package dev.mcc.core;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.Path;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.function.BooleanSupplier;
import static dev.mcc.core.AutomationGraphTest.*;
import static org.junit.jupiter.api.Assertions.*;
class AutomationProfilesTest {
 @TempDir Path directory;
 @Test void AutomaticActivationRequiresExplicitConfirmationAndProfilesPersist()throws Exception{Path path=directory.resolve("db");try(Database db=new Database(path);Automation a=new Automation(db,runtime(new AtomicInteger()),()->100000L)){Map<String,Object> body=new LinkedHashMap<>(simple());body.remove("confirmed");assertThrows(IllegalArgumentException.class,()->a.save(body,"admin","Admin"));String id=UUID.randomUUID().toString();a.saveProfile(Map.of("id",id,"name","Evening"),"admin","Admin");assertEquals(false,a.profiles().stream().filter(p->p.get("id").equals(id)).findFirst().orElseThrow().get("enabled"));assertThrows(IllegalArgumentException.class,()->a.saveProfile(Map.of("id",id,"name","Evening","enabled",true),"admin","Admin"));a.saveProfile(Map.of("id",id,"name","Evening","enabled",true,"confirmed",true),"admin","Admin");body.put("confirmed",true);body.put("profileId",id);a.save(body,"admin","Admin");assertThrows(IllegalArgumentException.class,()->a.deleteProfile(id,"admin","Admin"));}try(Database db=new Database(path);Automation a=new Automation(db,runtime(new AtomicInteger()),()->100000L)){assertEquals(2,a.profiles().size());assertTrue(a.hasSubscribers("interval"));assertEquals(1,a.list().size());}}
 @Test void TwoProfilesRunWithoutManualCommandAndDisabledProfileReceivesNothing()throws Exception{AtomicLong now=new AtomicLong(100000);AtomicInteger calls=new AtomicInteger();try(Database db=new Database(directory.resolve("db"));Automation a=new Automation(db,runtime(calls),now::get)){for(int i=0;i<2;i++){String id=UUID.randomUUID().toString();a.saveProfile(Map.of("id",id,"name","Profile"+i,"enabled",true,"confirmed",true),"admin","Admin");Map<String,Object> graph=new LinkedHashMap<>(simple());graph.put("profileId",id);a.save(graph,"admin","Admin");}now.addAndGet(31000);a.pulse();await(()->calls.get()==2);assertEquals(2,calls.get());for(var p:a.profiles())if(!p.get("id").equals(AutomationGraph.DEFAULT_PROFILE))a.saveProfile(Map.of("id",p.get("id"),"name",p.get("name"),"enabled",false),"admin","Admin");assertFalse(a.hasSubscribers("interval"));now.addAndGet(31000);a.pulse();Thread.sleep(100);assertEquals(2,calls.get());}}
 @Test void QueuedGameCallbackRechecksProfileCancellationBeforeApplying()throws Exception{AtomicReference<BooleanSupplier> guard=new AtomicReference<>();CompletableFuture<Object> pending=new CompletableFuture<>(){@Override public boolean cancel(boolean interrupt){return false;}};Automation.Runtime runtime=new Automation.Runtime(){public CompletableFuture<Object> read(String c,Map<String,Object> p,Map<String,Object> x){return CompletableFuture.completedFuture(true);}public CompletableFuture<Object> action(String c,Map<String,Object> p){return pending;}public CompletableFuture<Object> action(String c,Map<String,Object> p,BooleanSupplier allowed){guard.set(allowed);return pending;}};try(Database db=new Database(directory.resolve("db"));Automation a=new Automation(db,runtime,()->100000L)){var graph=simple();a.save(graph,"admin","Admin");a.run((String)graph.get("id"),"admin","Admin",Map.of(),true);await(()->guard.get()!=null);assertTrue(guard.get().getAsBoolean());a.enabled(false);assertFalse(guard.get().getAsBoolean());pending.complete(Map.of("applied",false));}}
 private static Automation.Runtime runtime(AtomicInteger calls){return new Automation.Runtime(){public CompletableFuture<Object> read(String c,Map<String,Object> p,Map<String,Object> x){return CompletableFuture.completedFuture(true);}public CompletableFuture<Object> action(String c,Map<String,Object> p){calls.incrementAndGet();return CompletableFuture.completedFuture(Map.of());}};}
 @Test void SignalAlreadyPolledBeforeOffCannotRunAfterModuleOn()throws Exception{AtomicLong now=new AtomicLong(100000);AtomicInteger calls=new AtomicInteger();AtomicBoolean armed=new AtomicBoolean();CountDownLatch polled=new CountDownLatch(1),release=new CountDownLatch(1);java.util.function.LongSupplier clock=()->{if(Thread.currentThread().getName().equals("MCC-Automation")&&armed.compareAndSet(true,false)){polled.countDown();try{if(!release.await(3,TimeUnit.SECONDS))throw new AssertionError("Release timed out");}catch(InterruptedException error){Thread.currentThread().interrupt();throw new IllegalStateException(error);}}return now.get();};try(Database db=new Database(directory.resolve("db"));Automation a=new Automation(db,runtime(calls),clock)){a.save(simple(),"admin","Admin");now.addAndGet(31000);armed.set(true);a.pulse();assertTrue(polled.await(3,TimeUnit.SECONDS));a.enabled(false);a.enabled(true);release.countDown();Thread.sleep(100);assertEquals(0,calls.get(),"Pre-disable polled signal must not be revived");a.pulse();await(()->calls.get()==1);}}
 @Test void SignalCapturedBeforeCooldownDoesNotMatureWhileWaitingInWorker()throws Exception{AtomicLong now=new AtomicLong(100000);AtomicInteger calls=new AtomicInteger();AtomicBoolean armed=new AtomicBoolean();CountDownLatch polled=new CountDownLatch(1),release=new CountDownLatch(1);java.util.function.LongSupplier clock=()->{if(Thread.currentThread().getName().equals("MCC-Automation")&&armed.compareAndSet(true,false)){polled.countDown();try{if(!release.await(3,TimeUnit.SECONDS))throw new AssertionError("Release timed out");}catch(InterruptedException error){Thread.currentThread().interrupt();throw new IllegalStateException(error);}}return now.get();};try(Database db=new Database(directory.resolve("db"));Automation a=new Automation(db,runtime(calls),clock)){a.save(simple(),"admin","Admin");now.addAndGet(29999);armed.set(true);a.pulse();assertTrue(polled.await(3,TimeUnit.SECONDS));now.incrementAndGet();release.countDown();Thread.sleep(100);assertEquals(0,calls.get(),"Eligibility belongs to capture time, not drain time");a.pulse();await(()->calls.get()==1);}}
 private static void await(BooleanSupplier value)throws Exception{long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(4);while(!value.getAsBoolean()&&System.nanoTime()<end)Thread.sleep(5);assertTrue(value.getAsBoolean());}
}
